     1	package com.pousadamarealta.controller;
     2	
     3	import com.pousadamarealta.domain.Document;
     4	import com.pousadamarealta.domain.Reservation;
     5	import com.pousadamarealta.dto.CreateReservationRequest;
     6	import com.pousadamarealta.dto.DocumentDto;
     7	import com.pousadamarealta.dto.ReservationDto;
     8	import com.pousadamarealta.exception.InvalidRequestException;
     9	import com.pousadamarealta.service.ReservationService;
    10	import io.javalin.http.Context;
    11	
    12	import java.time.LocalDate;
    13	import java.time.format.DateTimeFormatter;
    14	import java.time.format.DateTimeParseException;
    15	
    16	public class ReservationController {
    17	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    18	
    19	    private final ReservationService reservationService;
    20	
    21	    public ReservationController(ReservationService reservationService) {
    22	        this.reservationService = reservationService;
    23	    }
    24	
    25	    public void createReservation(Context ctx) {
    26	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    27	
    28	        validateCreateRequest(request);
    29	
    30	        LocalDate checkIn = parseDate(request.checkIn(), "checkIn");
    31	        LocalDate checkOut = parseDate(request.checkOut(), "checkOut");
    32	
    33	        if (!checkOut.isAfter(checkIn)) {
    34	            throw new InvalidRequestException("Check-out must be after check-in");
    35	        }
    36	
    37	        Reservation reservation = reservationService.createReservation(
    38	            request.roomNumber(),
    39	            request.guestName(),
    40	            request.guestEmail(),
    41	            request.guestCpf(),
    42	            checkIn,
    43	            checkOut,
    44	            request.guests(),
    45	            request.ratePlan()
    46	        );
    47	
    48	        ctx.status(201).json(ReservationDto.from(reservation));
    49	    }
    50	
    51	    public void getReservation(Context ctx) {
    52	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    53	        Reservation reservation = reservationService.getReservation(id);
    54	        ctx.json(ReservationDto.from(reservation));
    55	    }
    56	
    57	    public void confirmReservation(Context ctx) {
    58	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    59	        Reservation reservation = reservationService.confirmReservation(id);
    60	        ctx.json(ReservationDto.from(reservation));
    61	    }
    62	
    63	    public void checkIn(Context ctx) {
    64	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    65	        Reservation reservation = reservationService.checkIn(id);
    66	        ctx.json(ReservationDto.from(reservation));
    67	    }
    68	
    69	    public void checkOut(Context ctx) {
    70	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    71	        Reservation reservation = reservationService.checkOut(id);
    72	        Document document = reservationService.getDocument(id);
    73	        ctx.json(DocumentDto.from(document));
    74	    }
    75	
    76	    public void cancelReservation(Context ctx) {
    77	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    78	        Reservation reservation = reservationService.cancelReservation(id);
    79	        ctx.json(ReservationDto.from(reservation));
    80	    }
    81	
    82	    public void getDocument(Context ctx) {
    83	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    84	        Document document = reservationService.getDocument(id);
    85	        ctx.json(DocumentDto.from(document));
    86	    }
    87	
    88	    private void validateCreateRequest(CreateReservationRequest request) {
    89	        if (request.roomNumber() == null || request.roomNumber().isBlank()) {
    90	            throw new InvalidRequestException("roomNumber is required");
    91	        }
    92	        if (request.guestName() == null || request.guestName().isBlank()) {
    93	            throw new InvalidRequestException("guestName is required");
    94	        }
    95	        if (request.guestEmail() == null || request.guestEmail().isBlank()) {
    96	            throw new InvalidRequestException("guestEmail is required");
    97	        }
    98	        if (request.guestCpf() == null || request.guestCpf().isBlank()) {
    99	            throw new InvalidRequestException("guestCpf is required");
   100	        }
   101	        if (request.checkIn() == null || request.checkIn().isBlank()) {
   102	            throw new InvalidRequestException("checkIn is required");
   103	        }
   104	        if (request.checkOut() == null || request.checkOut().isBlank()) {
   105	            throw new InvalidRequestException("checkOut is required");
   106	        }
   107	        if (request.ratePlan() == null) {
   108	            throw new InvalidRequestException("ratePlan is required");
   109	        }
   110	    }
   111	
   112	    private LocalDate parseDate(String date, String fieldName) {
   113	        try {
   114	            return LocalDate.parse(date, DATE_FORMATTER);
   115	        } catch (DateTimeParseException e) {
   116	            throw new InvalidRequestException("Invalid date format for " + fieldName + ": " + date);
   117	        }
   118	    }
   119	}
