    31	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    32	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    33	                                        int guests, RatePlan ratePlan) {
    34	        Room room = roomRepository.findByNumber(roomNumber)
    35	            .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
    36	
    37	        if (guests < 1) {
    38	            throw new InvalidRequestException("Number of guests must be at least 1");
    39	        }
    40	
    41	        if (guests > room.capacity()) {
    42	            throw new CapacityExceededException("Room capacity exceeded");
    43	        }
    44	
    45	        if (reservationRepository.hasConflictingReservation(roomNumber, checkIn, checkOut, null)) {
    46	            throw new RoomUnavailableException("Room is not available for the selected dates");
    47	        }
    48	
    49	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    50	        BigDecimal subtotal = pricingService.calculateSubtotal(room.type(), checkIn, checkOut);
    51	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    52	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
    53	
    54	        Reservation reservation = new Reservation();
    55	        reservation.setRoomNumber(roomNumber);
    56	        reservation.setGuestName(guestName);
    57	        reservation.setGuestEmail(guestEmail);
    58	        reservation.setGuestCpf(guestCpf);
    59	        reservation.setCheckIn(checkIn);
    60	        reservation.setCheckOut(checkOut);
    61	        reservation.setGuests(guests);
    62	        reservation.setRatePlan(ratePlan);
    63	        reservation.setNights(nights);
    64	        reservation.setSubtotal(subtotal);
    65	        reservation.setDiscount(discount);
    66	        reservation.setTotal(total);
    67	        reservation.setStatus(ReservationStatus.PENDING);
    68	        reservation.setAmountPaid(BigDecimal.ZERO);
    69	        reservation.setRefund(null);
    70	
    71	        return reservationRepository.save(reservation);
