     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.RatePlan;
     4	import com.pousadamarealta.domain.RoomType;
     5	
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	import java.time.LocalDate;
     9	
    10	public class PricingService {
    11	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    12	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    13	
    14	    public BigDecimal calculateNightPrice(RoomType roomType, LocalDate night) {
    15	        BigDecimal basePrice = roomType.getNightlyRate();
    16	        if (isHighSeason(night)) {
    17	            basePrice = basePrice.multiply(HIGH_SEASON_MULTIPLIER);
    18	        }
    19	        return round(basePrice);
    20	    }
    21	
    22	    public BigDecimal calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
    23	        BigDecimal subtotal = BigDecimal.ZERO;
    24	        LocalDate current = checkIn;
    25	
    26	        while (current.isBefore(checkOut)) {
    27	            subtotal = subtotal.add(calculateNightPrice(roomType, current));
    28	            current = current.plusDays(1);
    29	        }
    30	
    31	        return round(subtotal);
    32	    }
    33	
    34	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    35	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    36	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
    37	        }
    38	        return BigDecimal.ZERO;
    39	    }
    40	
    41	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    42	        return round(subtotal.subtract(discount));
    43	    }
    44	
    45	    private boolean isHighSeason(LocalDate date) {
    46	        int month = date.getMonthValue();
    47	        int day = date.getDayOfMonth();
    48	
    49	        if (month == 7) {
    50	            return true;
    51	        }
    52	
    53	        if (month == 12 && day >= 15) {
    54	            return true;
    55	        }
    56	
    57	        if (month == 1 || month == 2) {
    58	            return true;
    59	        }
    60	
    61	        return false;
    62	    }
    63	
    64	    private BigDecimal round(BigDecimal value) {
    65	        return value.setScale(2, RoundingMode.HALF_EVEN);
    66	    }
    67	}
