   103	    public Reservation checkOut(Long id) {
   104	        Reservation reservation = getReservation(id);
   105	
   106	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   107	            throw new OperationNotAllowedException("Only checked-in reservations can be checked out");
   108	        }
   109	
   110	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   111	        return reservationRepository.save(reservation);
   112	    }
   113	
   114	    public Reservation cancelReservation(Long id) {
   115	        Reservation reservation = getReservation(id);
   116	
   117	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   118	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   119	            throw new OperationNotAllowedException("Only pending or confirmed reservations can be cancelled");
   120	        }
   121	
   122	        BigDecimal refundAmount = BigDecimal.ZERO;
   123	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
   124	            refundAmount = reservation.getAmountPaid();
   125	        }
   126	
   127	        reservation.setStatus(ReservationStatus.CANCELLED);
   128	        reservation.setRefund(refundAmount);
   129	        return reservationRepository.save(reservation);
   130	    }
   131	
   132	    public Reservation getReservation(Long id) {
   133	        return reservationRepository.findById(id)
   134	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found: " + id));
   135	    }
   136	
   137	    public Document getDocument(Long id) {
   138	        Reservation reservation = getReservation(id);
   139	
   140	        if (reservation.getStatus() == ReservationStatus.PENDING) {
   141	            throw new OperationNotAllowedException("Document only available for paid reservations");
   142	        }
   143	
   144	        if (reservation.getStatus() == ReservationStatus.CANCELLED) {
   145	            throw new OperationNotAllowedException("Document only available for paid reservations");
   146	        }
   147	
   148	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
   149	        return documentService.generateDocument(reservation, room);
   150	    }
