   212	              AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
   213	            ORDER BY check_in, id
   214	        """;
   215	
   216	        return executeQuery(sql, stmt -> {
   217	            stmt.setDate(1, Date.valueOf(start));
   218	            stmt.setDate(2, Date.valueOf(end));
   219	        });
   220	    }
   221	
   222	    private List<Reservation> executeQuery(String sql, PreparedStatementSetter setter) {
   223	        List<Reservation> reservations = new ArrayList<>();
   224	
   225	        try (Connection conn = dataSource.getConnection();
   226	             PreparedStatement stmt = conn.prepareStatement(sql)) {
   227	
   228	            setter.set(stmt);
   229	
   230	            try (ResultSet rs = stmt.executeQuery()) {
   231	                while (rs.next()) {
   232	                    reservations.add(mapReservation(rs));
   233	                }
   234	            }
   235	        } catch (SQLException e) {
   236	            throw new RuntimeException("Failed to query reservations", e);
   237	        }
   238	
   239	        return reservations;
   240	    }
   241	
   242	    private Reservation mapReservation(ResultSet rs) throws SQLException {
   243	        return new Reservation(
   244	            rs.getLong("id"),
   245	            rs.getString("room_number"),
   246	            rs.getString("guest_name"),
   247	            rs.getString("guest_email"),
   248	            rs.getString("guest_cpf"),
   249	            rs.getDate("check_in").toLocalDate(),
   250	            rs.getDate("check_out").toLocalDate(),
   251	            rs.getInt("guests"),
   252	            RatePlan.valueOf(rs.getString("rate_plan")),
   253	            rs.getInt("nights"),
   254	            rs.getBigDecimal("subtotal"),
   255	            rs.getBigDecimal("discount"),
   256	            rs.getBigDecimal("total"),
   257	            ReservationStatus.valueOf(rs.getString("status")),
   258	            rs.getBigDecimal("amount_paid"),
   259	            rs.getBigDecimal("refund")
   260	        );
   261	    }
   262	
   263	    @FunctionalInterface
   264	    private interface PreparedStatementSetter {
   265	        void set(PreparedStatement stmt) throws SQLException;
   266	    }
   267	}
